// src/Component/ApplicantsJob.js
import React, { useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  fetchApplicants,
  updateApplicantStatus,
} from "../Features/ApplicantsSlice";
import { useSearchParams, useNavigate } from "react-router-dom";
import "../Styles/ApplicantsJob.css";

const ApplicantsJob = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const [params] = useSearchParams();

  const jobId = params.get("jobId");
  const { list, isLoading } = useSelector((state) => state.applicants);

  useEffect(() => {
    if (jobId) dispatch(fetchApplicants(jobId));
  }, [dispatch, jobId]);

  const handleAction = (id, status) => {
    dispatch(updateApplicantStatus({ applicationId: id, status }));
  };

  if (isLoading) return <p>Loading applicants...</p>;

  return (
    <div className="applicants-page">
      <h1 className="title">
        Applicants for <span className="accent">Job</span>
      </h1>

      {list.length === 0 ? (
        <p className="empty">No applicants yet.</p>
      ) : (
        list.map((app) => (
          <div key={app._id} className="applicant-card">
            <div>
              <h3>{app.applicantName}</h3>
              <p>Email: {app.applicantEmail}</p>
              <p>Status: {app.status}</p>
            </div>

            <div className="actions">
              <button onClick={() => navigate(`/company-chat/${app._id}`)}>
                Chat 💬
              </button>

              <button
                className="accept-btn"
                onClick={() => handleAction(app._id, "Accepted")}
              >
                Accept
              </button>

              <button
                className="reject-btn"
                onClick={() => handleAction(app._id, "Rejected")}
              >
                Reject
              </button>
            </div>
          </div>
        ))
      )}
    </div>
  );
};

export default ApplicantsJob;
